* - The messages of the session
     * - The user that created the session
     *
     * @param variant      the variant of the pipeline
     * @param session      the chat session
     * @param eventVariant the event variant if this function triggers a pipeline execution due to a specific event
     * @param post         the post the session is about
     */
    public void executeTutorSuggestionPipeline(String variant, IrisTutorSuggestionSession session, Optional<String> eventVariant, Post post) {
        var course = post.getCoursePostingBelongsTo();
        if (course == null) {
            throw new IllegalStateException("Course is null for post " + post.getId());
        }
        // @formatter:off
        executePipeline(
            "tutor-suggestion",
            variant,
            eventVariant,
            pyrisJobService.addTutorSuggestionJob(post.getId(), course.getId(), session.getId()),
            executionDto -> {
                var user = userRepository.findByIdElseThrow(session.getUserId());
                var exercise = resolveExerciseForPost(post);
                PyrisProgrammingExerciseDTO programmingExerciseDTO = null;
                PyrisTextExerciseDTO textExerciseDTO = null;
                Optional<Integer> exerciseId = Optional.empty();
                if (exercise instanceof ProgrammingExercise) {
                    // Reload with template and solution participation as they are required to build the DTO but are not eagerly loaded on the post's channel
                    var programmingExercise = programmingExerciseRepository.findByIdWithTemplateAndSolutionParticipationElseThrow(exercise.getId());
                    programmingExerciseDTO = pyrisDTOService.toPyrisProgrammingExerciseDTO(programmingExercise);
                    exerciseId = Optional.of(exercise.getId().intValue());
                }
                else if (exercise instanceof TextExercise textExercise) {
                    textExerciseDTO = PyrisTextExerciseDTO.of(textExercise);
                    exerciseId = Optional.of(exercise.getId().intValue());
                }
                return new PyrisTutorSuggestionPipelineExecutionDTO(
                    new PyrisCourseDTO(course),
                    exerciseId,
                    new PyrisPostDTO(post),
                    pyrisDTOService.toPyrisMessageDTOList(session.getMessages()),
                    new PyrisUserDTO(user),
                    executionDto.settings(),
                    executionDto.initialStages(),
                    programmingExerciseDTO,
                    textExerciseDTO
                );
            },
            stages -> irisChatWebsocketService.sendStatusUpdate(session, stages)
        );
        // @formatter:on
    }

